import React from "react";
import { notFound } from "next/navigation";
import Link from "next/link";
import type { Metadata } from "next";
import { posts, getPostBySlug } from "@/data/posts";
import { getProductBySlug } from "@/data/products";
import ProductCard from "@/components/ProductCard";
import AffiliateDisclosure from "@/components/AffiliateDisclosure";
import VetDisclaimer from "@/components/VetDisclaimer";

export async function generateStaticParams() {
  return posts.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  if (!post) return {};
  return { title: post.title, description: post.excerpt };
}

interface ArticleSection {
  heading?: string;
  text?: string;
  list?: string[];
  table?: { headers: string[]; rows: string[][] };
  faqs?: { q: string; a: string }[];
  inlineLinks?: Array<{phrase: string; href: string}>;
}


function renderWithLinks(text: string, links?: Array<{phrase: string; href: string}>): React.ReactNode {
  if (!links?.length) return <>{text}</>
  for (const link of links) {
    const idx = text.indexOf(link.phrase)
    if (idx !== -1) {
      const before = text.slice(0, idx)
      const after = text.slice(idx + link.phrase.length)
      return (
        <>
          {before.length > 0 && renderWithLinks(before, links.filter(l => l.phrase !== link.phrase))}
          <Link href={link.href} className="text-cyan-700 underline hover:text-cyan-900 font-medium">{link.phrase}</Link>
          {after.length > 0 && renderWithLinks(after, links.filter(l => l.phrase !== link.phrase))}
        </>
      )
    }
  }
  return <>{text}</>
}

